import{c as e,Q as a,j as d,m as r}from"./chunks/framework.rWdQudnF.js";const b=JSON.parse('{"title":"存储系统","description":"","frontmatter":{"title":"存储系统"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成/存储系统.md","filePath":"综合知识/系统基础/计算机组成/存储系统.md","lastUpdated":null}'),n={name:"综合知识/系统基础/计算机组成/存储系统.md"};function l(o,t,s,i,h,g){return a(),d("div",null,[...t[0]||(t[0]=[r('<h3 id="存储系统" tabindex="-1">存储系统 <a class="header-anchor" href="#存储系统" aria-label="Permalink to &quot;存储系统&quot;">​</a></h3><h4 id="计算机存储结构层次图" tabindex="-1">计算机存储结构层次图 <a class="header-anchor" href="#计算机存储结构层次图" aria-label="Permalink to &quot;计算机存储结构层次图&quot;">​</a></h4><h5 id="分级存储" tabindex="-1">分级存储 <a class="header-anchor" href="#分级存储" aria-label="Permalink to &quot;分级存储&quot;">​</a></h5><blockquote><p>目的：解决存储<strong>容量、成本和速度</strong>之间的矛盾。按 CPU 物理距离分 4 层（由近→远）：片上缓存 → 片外缓存 → 主存（内存）→ 外存。速度依次降低，容量依次提高。</p></blockquote><p><strong>两级存储</strong>：Cache-主存、主存-辅存（虚拟存储体系）。</p><p><strong>局部性原理</strong>：</p><ul><li><strong>时间局部性</strong>：刚被访问的数据近期可能再次被访问</li><li><strong>空间局部性</strong>：相邻地址的数据可能被连续访问</li></ul><blockquote><p>🎯 一句话结论：<strong>局部性原理不仅适用于循环程序</strong>，数组访问（空间局部性）、子程序调用等也体现局部性。Cache 设计的理论依据正是程序的局部性原理。</p></blockquote><h4 id="局部性原理" tabindex="-1">局部性原理 <a class="header-anchor" href="#局部性原理" aria-label="Permalink to &quot;局部性原理&quot;">​</a></h4><h4 id="高速缓存-cache" tabindex="-1">高速缓存 Cache <a class="header-anchor" href="#高速缓存-cache" aria-label="Permalink to &quot;高速缓存 Cache&quot;">​</a></h4><h5 id="cache-地址映射" tabindex="-1">Cache 地址映射 <a class="header-anchor" href="#cache-地址映射" aria-label="Permalink to &quot;Cache 地址映射&quot;">​</a></h5><blockquote><p>在 CPU 工作时，送出的是主存地址，需转换为 Cache 地址，称为<strong>地址映像</strong>，由<strong>硬件自动完成</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>映射方式</th><th>特点</th><th style="text-align:center;">块冲突概率</th></tr></thead><tbody><tr><td><strong>直接映像</strong></td><td>主存块与 Cache 块号相同才能命中，变换简单但不灵活</td><td style="text-align:center;"><strong>最高</strong></td></tr><tr><td><strong>全相联映像</strong></td><td>主存任意块可调入 Cache 任意块，变换复杂速度慢</td><td style="text-align:center;"><strong>最低</strong></td></tr><tr><td><strong>组相联映像</strong></td><td>组间直接映像 + 组内全相联映像，前两者折中</td><td style="text-align:center;">中</td></tr></tbody></table><blockquote><p>块冲突概率：<strong>直接映像 &gt; 组相联映像 &gt; 全相联映像</strong>。</p></blockquote><h5 id="相联存取-按内容寻址" tabindex="-1">相联存取（按内容寻址） <a class="header-anchor" href="#相联存取-按内容寻址" aria-label="Permalink to &quot;相联存取（按内容寻址）&quot;">​</a></h5><blockquote><p>🎯 一句话结论：<strong>相联存取根据访问内容（而非地址）决定存储单元</strong>，常用于 <strong>Cache</strong> 中。</p></blockquote><table tabindex="0"><thead><tr><th>存取方式</th><th>机制</th><th>应用</th></tr></thead><tbody><tr><td>顺序存取</td><td>按顺序定位数据</td><td>磁带</td></tr><tr><td>直接存取</td><td>直接定位到块，再顺序查找</td><td>磁盘</td></tr><tr><td>随机存取</td><td>按地址直接访问任意单元</td><td>主存（DRAM）</td></tr><tr><td><strong>相联存取</strong></td><td><strong>按内容而非地址</strong>查找</td><td><strong>Cache</strong>（TLB也用到）</td></tr></tbody></table><blockquote><p>相联存取能在一个存储周期内将关键字与所有单元同时比较，硬件复杂度高但速度快。</p></blockquote><h4 id="虚拟存储器" tabindex="-1">虚拟存储器 <a class="header-anchor" href="#虚拟存储器" aria-label="Permalink to &quot;虚拟存储器&quot;">​</a></h4><h4 id="存储介质易失性分类" tabindex="-1">存储介质易失性分类 <a class="header-anchor" href="#存储介质易失性分类" aria-label="Permalink to &quot;存储介质易失性分类&quot;">​</a></h4><blockquote><p>🎯 一句话结论：<strong>SRAM/DRAM/寄存器 掉电丢失数据（易失性），Flash/SSD/HDD/ROM 掉电保持数据（非易失性）</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>介质</th><th style="text-align:center;">易失性</th><th style="text-align:center;">速度</th><th>典型用途</th></tr></thead><tbody><tr><td>寄存器</td><td>触发器</td><td style="text-align:center;">易失</td><td style="text-align:center;"><strong>最快</strong></td><td>CPU 内部</td></tr><tr><td>SRAM</td><td>晶体管</td><td style="text-align:center;">易失</td><td style="text-align:center;">很快</td><td>Cache（L1/L2/L3）</td></tr><tr><td>DRAM</td><td>电容</td><td style="text-align:center;">易失（需刷新）</td><td style="text-align:center;">中</td><td>主存（内存条）</td></tr><tr><td>Flash</td><td>浮栅晶体管</td><td style="text-align:center;"><strong>非易失</strong></td><td style="text-align:center;">慢于DRAM</td><td>SSD、U盘</td></tr><tr><td>HDD</td><td>磁介质</td><td style="text-align:center;"><strong>非易失</strong></td><td style="text-align:center;"><strong>最慢</strong></td><td>机械硬盘</td></tr></tbody></table><blockquote><p>⚠️ <strong>DRAM 访问速度远高于 SSD/HDD</strong>，常见干扰项说&quot;DRAM 速度远低于 SSD&quot;是错误的。</p></blockquote><h4 id="dram-与-ddr-sdram-特性" tabindex="-1">DRAM 与 DDR SDRAM 特性 <a class="header-anchor" href="#dram-与-ddr-sdram-特性" aria-label="Permalink to &quot;DRAM 与 DDR SDRAM 特性&quot;">​</a></h4><blockquote><p>🎯 一句话结论：<strong>DDR SDRAM 在时钟上升沿和下降沿各传输一次数据</strong>，同等时钟频率下带宽是普通 SDRAM 的 2 倍。</p></blockquote><ul><li>DRAM 用电容存储，需<strong>定时刷新</strong>以保持数据</li><li>DDR（Double Data Rate）：<strong>时钟上下沿都传输</strong>，实现加倍速率</li><li>速度链：CPU 寄存器 &gt; Cache(SRAM) &gt; 主存(DRAM) &gt; SSD(Flash) &gt; HDD(磁盘)</li></ul><h4 id="磁盘" tabindex="-1">磁盘 <a class="header-anchor" href="#磁盘" aria-label="Permalink to &quot;磁盘&quot;">​</a></h4><h5 id="磁盘结构与调度算法" tabindex="-1">磁盘结构与调度算法 <a class="header-anchor" href="#磁盘结构与调度算法" aria-label="Permalink to &quot;磁盘结构与调度算法&quot;">​</a></h5><p><strong>磁盘三大要素</strong>：磁头（Head）、柱面（Cylinder，所有盘面同位置磁道集合）、扇区（Sector，最小存储单元）。</p><table tabindex="0"><thead><tr><th>算法</th><th>说明</th><th>特点</th></tr></thead><tbody><tr><td><strong>FCFS</strong>（先来先服务）</td><td>按请求顺序调度</td><td>公平但效率低</td></tr><tr><td><strong>SSTF</strong>（最短寻道时间优先）</td><td>离当前磁道最近的请求优先</td><td>可能产生&quot;<strong>饥饿</strong>&quot;</td></tr><tr><td><strong>SCAN</strong>（扫描/电梯算法）</td><td>磁头双向移动到底才掉头</td><td>与电梯类似</td></tr><tr><td><strong>CSCAN</strong>（单向扫描）</td><td>只做单向移动</td><td>更均匀的等待时间</td></tr></tbody></table><h5 id="命中率计算" tabindex="-1">命中率计算 <a class="header-anchor" href="#命中率计算" aria-label="Permalink to &quot;命中率计算&quot;">​</a></h5><blockquote><p>平均访问时间 = 命中率 × Cache 访问时间 +（1 - 命中率）× 主存访问时间。</p></blockquote><h5 id="替换算法" tabindex="-1">替换算法 <a class="header-anchor" href="#替换算法" aria-label="Permalink to &quot;替换算法&quot;">​</a></h5><table tabindex="0"><thead><tr><th>算法</th><th>说明</th></tr></thead><tbody><tr><td>随机替换</td><td>随机选择被替换块</td></tr><tr><td>先进先出（FIFO）</td><td>替换最先进入 Cache 的块</td></tr><tr><td><strong>近期最少使用（LRU）</strong></td><td>替换近期最少使用的块</td></tr><tr><td>优化替换</td><td>先执行一次程序统计替换情况，第二次用最优方式</td></tr></tbody></table><h3 id="硬盘格式化容量" tabindex="-1">硬盘格式化容量 <a class="header-anchor" href="#硬盘格式化容量" aria-label="Permalink to &quot;硬盘格式化容量&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>格式化容量 = 记录面数 × 每面磁道数 × 每道扇区数 × 每扇区字节数</strong>。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>格式化容量 = 记录面数 × 磁道数/面 × 扇区数/道 × 字节数/扇区</span></span></code></pre></div><p><strong>计算示例</strong>：</p><blockquote><p>4 个记录面，每面 1000 磁道，每道 200 扇区，每扇区 512 字节</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>容量 = 4 × 1000 × 200 × 512 = 409,600,000 字节 ≈ 400MB</span></span></code></pre></div><p>⚠️ <strong>非格式化容量</strong> ≠ 格式化容量：</p><ul><li>非格式化容量 = 记录面数 × 磁道数 × 内圈周长 × 最大位密度（一般不考）</li><li>格式化后每个扇区会有间隙、同步字段等开销，实际可用容量更小</li></ul><h3 id="硬盘存取时间" tabindex="-1">硬盘存取时间 <a class="header-anchor" href="#硬盘存取时间" aria-label="Permalink to &quot;硬盘存取时间&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>存取时间 = 寻道时间 + 等待时间 + 读/写时间</strong>，其中寻道时间最长，是性能瓶颈。</p></blockquote><table tabindex="0"><thead><tr><th>组成部分</th><th>含义</th><th style="text-align:center;">量级</th></tr></thead><tbody><tr><td><strong>寻道时间</strong></td><td>磁头移动到目标磁道（柱面）的时间</td><td style="text-align:center;">最长（ms 级）</td></tr><tr><td><strong>等待时间</strong>（旋转延迟）</td><td>目标扇区旋转到磁头下方的时间</td><td style="text-align:center;">平均为旋转半圈时间</td></tr><tr><td><strong>读/写时间</strong>（传输时间）</td><td>实际数据读写的时间</td><td style="text-align:center;">相对最短</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>平均存取时间 = 平均寻道时间 + 平均等待时间 + 传输时间</span></span></code></pre></div><blockquote><p>平均等待时间 ≈ 1 / (2 × 转速)，如 7200rpm → 平均等待 ≈ 4.17ms</p></blockquote><h3 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h3><table tabindex="0"><thead><tr><th>易错点</th><th>正解</th></tr></thead><tbody><tr><td>忘了乘记录面数</td><td>硬盘有多个盘面，格式化容量公式第一项就是<strong>记录面数</strong></td></tr><tr><td>存取时间 = 寻道 + 等待</td><td>漏了<strong>读/写（传输）时间</strong>，虽然它最小但不能省略</td></tr><tr><td>MB 换算</td><td>1MB = 10^6 还是 2^20？硬盘厂商用 10^6，考题一般用 1024 进制；注意题干上下文</td></tr></tbody></table><h3 id="raid-级别速查" tabindex="-1">RAID 级别速查 <a class="header-anchor" href="#raid-级别速查" aria-label="Permalink to &quot;RAID 级别速查&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>RAID0 无冗余性能最高，RAID1 全镜像最安全，RAID5 分布式奇偶校验（允许坏1块），RAID6 双奇偶校验（允许坏2块），RAID10 先镜像再条带</strong>。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">级别</th><th style="text-align:center;">冗余</th><th style="text-align:center;">最少盘数</th><th style="text-align:left;">有效容量</th><th style="text-align:center;">允许坏盘</th><th style="text-align:center;">读性能</th><th style="text-align:center;">写性能</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>RAID0</strong></td><td style="text-align:center;">无</td><td style="text-align:center;">2</td><td style="text-align:left;">n×min</td><td style="text-align:center;">0</td><td style="text-align:center;">高</td><td style="text-align:center;">高</td></tr><tr><td style="text-align:left;"><strong>RAID1</strong></td><td style="text-align:center;">镜像</td><td style="text-align:center;">2</td><td style="text-align:left;">1×min</td><td style="text-align:center;">n-1</td><td style="text-align:center;">中</td><td style="text-align:center;">中</td></tr><tr><td style="text-align:left;"><strong>RAID5</strong></td><td style="text-align:center;">1块校验</td><td style="text-align:center;">3</td><td style="text-align:left;">(n-1)×min</td><td style="text-align:center;"><strong>1</strong></td><td style="text-align:center;">高</td><td style="text-align:center;">中</td></tr><tr><td style="text-align:left;"><strong>RAID6</strong></td><td style="text-align:center;">2块校验</td><td style="text-align:center;">4</td><td style="text-align:left;">(n-2)×min</td><td style="text-align:center;"><strong>2</strong></td><td style="text-align:center;">高</td><td style="text-align:center;">低</td></tr><tr><td style="text-align:left;"><strong>RAID10</strong></td><td style="text-align:center;">镜像+条带</td><td style="text-align:center;">4</td><td style="text-align:left;">(n/2)×min</td><td style="text-align:center;">每组最多1</td><td style="text-align:center;">高</td><td style="text-align:center;">中</td></tr></tbody></table><h3 id="容量计算公式" tabindex="-1">容量计算公式 <a class="header-anchor" href="#容量计算公式" aria-label="Permalink to &quot;容量计算公式&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>RAID 有效容量 = (盘数 - 校验盘数) × 最小盘容量</strong>，校验盘数 RAID5=1, RAID6=2, RAID0=0。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有效容量 = (N - P) × min(所有盘容量)</span></span></code></pre></div><ul><li>N = 磁盘总数</li><li>P = 校验盘数量（RAID0=0, RAID5=1, RAID6=2）</li><li>若各盘容量不同，取<strong>最小值</strong></li></ul><p><strong>示例</strong>：4 块 80T 硬盘组 RAID6，有效容量 = (4-2)×80 = <strong>160T</strong>。</p><h3 id="raid-目标" tabindex="-1">RAID 目标 <a class="header-anchor" href="#raid-目标" aria-label="Permalink to &quot;RAID 目标&quot;">​</a></h3><blockquote><p>🎯 一句话结论：RAID 的核心目的是<strong>兼顾数据安全性与磁盘 I/O 性能</strong>，而非单纯扩大容量或降低成本。</p></blockquote><ul><li>RAID 通过<strong>冗余</strong>提升数据安全性（镜像/奇偶校验）</li><li>RAID 通过**条带化（striping）**将数据分散到多盘，并行读写提升 I/O 性能</li></ul><h3 id="⚠️-常见坑-1" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑-1" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h3><table tabindex="0"><thead><tr><th>易错点</th><th>正解</th></tr></thead><tbody><tr><td>RAID0 性能高是因为条带化 I/O 并行，<strong>但无任何冗余保护</strong></td><td>不要误以为 RAID0 有数据保护</td></tr><tr><td>RAID5 只允许坏 <strong>1 块</strong>盘，RAID6 允许坏 <strong>2 块</strong></td><td>不要记反</td></tr><tr><td>容量计算取<strong>最小盘容量</strong>，各盘不同时不能用平均值</td><td>实际场景中各盘容量通常相同</td></tr></tbody></table>',62)])])}const u=e(n,[["render",l]]);export{b as __pageData,u as default};
